if (msg.payload !== 'saveShelly') return null;

global.set('shellyDevices', msg.shellyDevices);

msg.saveResult = 'Ulozeno';
return msg;

const shellyDevices = global.get('shellyDevices') || global.get('defaultShellyDevices') || { smoke: [] };

// Vytvoř lookup mapu z konfigurace
const devices = {};
(shellyDevices.smoke || []).forEach(d => {
    devices[d.id] = { name: d.name, ip: d.ip };
});

const key = msg.topic.split('/')[0];
const dev = devices[key];
const ntfyUrl = (global.get('config') || {}).ntfyConfig?.url || '';

if (!dev) {
    //node.warn("Neznámé zařízení: " + key);
    return null;
}

const method = msg.payload.method;
const p = msg.payload.params;
if (!p) return null;

if (method === 'NotifyStatus') return null;

let event = null, battery_pct, battery_v, alarm = false, rssi, wakeup;

if (method === 'NotifyFullStatus' && p['devicepower:0']) {
    event = 'full_status';
    battery_v = p['devicepower:0'].battery.V;
    battery_pct = p['devicepower:0'].battery.percent;
    alarm = p['smoke:0'] ? p['smoke:0'].alarm : false;
    rssi = p.wifi ? p.wifi.rssi : null;
    wakeup = (p.wakeup_reason && p.wakeup_reason.cause) ? p.wakeup_reason.cause : 'timer';
} else if (method === 'NotifyEvent' && p.events && p.events.length > 0) {
    const ev = p.events[0];
    if (ev.event === 'sleep') return null;
    if (ev.event === 'alarm_test') event = 'alarm_test';
    else if (ev.component === 'smoke:0') event = ev.state ? 'alarm_on' : 'alarm_off';
}
if (!event) return null;

if (event === 'alarm_test') {
    return [null, {
        payload: 'Test cidla: ' + dev.name,
        headers: { Title: 'Test - ' + dev.name, Priority: 'low', Tags: 'test_tube' },
        url: ntfyUrl
    }];
}

const ts = Date.now();

// kratky cas pro zobrazeni: "17.6. 19:11"
function fmtTime(epoch) {
    const dt = new Date(epoch);
    return dt.getDate() + '.' + (dt.getMonth() + 1) + '. ' +
        String(dt.getHours()).padStart(2, '0') + ':' +
        String(dt.getMinutes()).padStart(2, '0');
}

const mDash = {
    topic: key,
    device_name: dev.name,
    device_ip: 'http://' + dev.ip,
    alarm: alarm,
    last_seen: ts,
    // strukturovana data pro template
    ok: !alarm,
    bat_pct: battery_pct,
    bat_v: battery_v,
    rssi: rssi,
    wakeup: wakeup,
    time_str: fmtTime(ts)
};

// Ulož poslední stav do persistentního bufferu
const buf = global.get('smokeBuffer') || {};
buf[key] = mDash;
global.set('smokeBuffer', buf);

// =============================================================================
// LINEA API R2.2 - READ-ONLY SHELLY SMOKE SNAPSHOT
// =============================================================================
// Posila posledni znamy stav vsech nakonfigurovanych kourovych cidel.
// IP adresa ani interni Shelly ID se do API neexportuji.
// =============================================================================
const apiSmokeNow = Date.now();

const apiSmokeDetectors = (shellyDevices.smoke || []).map(cfg => {
    const s = buf[cfg.id] || null;
    const lastSeenMs = s && Number(s.last_seen) > 0 ? Number(s.last_seen) : null;

    return {
        name: cfg.name || null,
        alarm: s ? !!s.alarm : null,
        ok: s && s.ok !== undefined ? s.ok : null,
        batteryPct: s && s.bat_pct !== undefined ? s.bat_pct : null,
        batteryVoltageV: s && s.bat_v !== undefined ? s.bat_v : null,
        rssiDbm: s && s.rssi !== undefined ? s.rssi : null,
        wakeupReason: s && s.wakeup !== undefined ? s.wakeup : null,
        lastSeen: lastSeenMs ? new Date(lastSeenMs).toISOString() : null,
        ageSec: lastSeenMs ? Math.max(0, Math.floor((apiSmokeNow - lastSeenMs) / 1000)) : null
    };
});

global.set("lineaApiShellySmokeState", {
    updatedAt: new Date(apiSmokeNow).toISOString(),
    smokeDetectors: apiSmokeDetectors
});


let mNtfy = null;

if (event === 'alarm_on') {
    mNtfy = {
        payload: 'POZAR! ' + dev.name,
        headers: { Title: 'POZAR - ' + dev.name, Priority: 'urgent', Tags: 'fire,rotating_light' },
        url: ntfyUrl
    };
} else if (event === 'alarm_off') {
    mNtfy = {
        payload: 'Poplach ukoncen. ' + dev.name,
        headers: { Title: 'Kour konec - ' + dev.name, Priority: 'default', Tags: 'white_check_mark' },
        url: ntfyUrl
    };
} else if (event === 'full_status' && battery_pct < 20) {
    mNtfy = {
        payload: 'Baterie ' + dev.name + ': ' + battery_pct + '%',
        headers: { Title: 'Nizka baterie - ' + dev.name, Priority: 'high', Tags: 'battery,warning' },
        url: ntfyUrl
    };
}

return [mDash, mNtfy];

