// ===== switch_logic - "Switch - hlavni logika" =====
// Plocha struktura: kazdy zaznam ve switches[] = jeden kanal.
// kind: 'output' (default) nebo 'input'. order = poradi karty (drag&drop).

const shellyDevices = global.get('shellyDevices') || global.get('defaultShellyDevices') || { switches: [] };

const lookup = {};       // vystupy:  klic mqtt_id + ':' + channel
const inputLookup = {};  // vstupy:   klic mqtt_id + '#' + channel
const ipByMqtt = {};     // IP podle mqtt_id (castecna shoda u neznamych)

(shellyDevices.switches || []).forEach((d, i) => {
    if (!d.mqtt_id) return;
    if (d.ip && !ipByMqtt[d.mqtt_id]) ipByMqtt[d.mqtt_id] = d.ip;

    const ch = (d.channel !== undefined ? d.channel : 0);
    const named = d.name && String(d.name).trim() !== '';
    const isInput = (d.kind === 'input');
    const ord = (d.order !== undefined ? d.order : i);

    if (!named) return; // bez nazvu nezobrazuj (ani vystup, ani vstup)

    if (isInput) {
        inputLookup[d.mqtt_id + '#' + ch] = { name: d.name, ip: d.ip, mqtt_id: d.mqtt_id, index: ch, order: ord };
    } else {
        lookup[d.mqtt_id + ':' + ch] = { name: d.name, ip: d.ip, mqtt_id: d.mqtt_id, channel: ch, order: ord };
    }
});

const fmt = (v, d) => (v === null || v === undefined ? '--' : Number(v).toFixed(d));

// =============================================================================
// LINEA API R2.2 - READ-ONLY SHELLY SNAPSHOT
// =============================================================================
// Zamerne se neexportuji IP adresy, MQTT ID, spotreba, proud ani napeti.
// Pro analytiku se pouziva pouze pojmenovany kanal a jeho stav.
// =============================================================================
function rebuildShellyApiSnapshot(context) {
    const devices = [];

    (shellyDevices.switches || []).forEach((d, i) => {
        if (!d || !d.name || !String(d.name).trim() || !d.mqtt_id) return;

        const channel = (d.channel !== undefined ? d.channel : 0);
        const kind = d.kind === 'input' ? 'input' : 'output';

        let state = null;
        if (kind === 'input') {
            const st = context.get('in_' + d.mqtt_id + '#' + channel) || {};
            state = st.state === undefined ? null : st.state;
        } else {
            const st = context.get('sw_' + d.mqtt_id + ':' + channel) || {};
            state = st.output === undefined ? null : st.output;
        }

        devices.push({
            name: String(d.name),
            kind,
            channel,
            state: state === null ? null : !!state,
            available: state !== null
        });
    });

    global.set("lineaApiShellyState", {
        updatedAt: new Date().toISOString(),
        devices
    });
}


function emit(node, context, key, dev) {
    const state = context.get('sw_' + key) || { output: null, apower: null, voltage: null, current: null, energy: null };
    const hasData = (state.output !== null || state.apower !== null || state.voltage !== null || state.energy !== null);
    node.send({
        topic:       key,
        kind:        'output',
        order:       (dev.order !== undefined ? dev.order : 9999),
        unknown:     false,
        has_data:    hasData,
        device_name: dev.name,
        device_ip:   'http://' + dev.ip,
        mqtt_id:     dev.mqtt_id,
        channel:     dev.channel,
        output:      state.output,
        power_w:     fmt(state.apower, 1),
        voltage_v:   fmt(state.voltage, 1),
        current_a:   fmt(state.current, 2),
        energy_kwh:  (state.energy === null || state.energy === undefined ? '--' : (state.energy / 1000).toFixed(3))
    });
    rebuildShellyApiSnapshot(context);
}

function emitInput(node, context, ikey, dev) {
    const st = context.get('in_' + ikey) || { state: null };
    node.send({
        topic:       ikey,
        kind:        'input',
        order:       (dev.order !== undefined ? dev.order : 9999),
        unknown:     false,
        has_data:    st.state !== null,
        device_name: dev.name,
        device_ip:   dev.ip ? ('http://' + dev.ip) : null,
        mqtt_id:     dev.mqtt_id,
        index:       dev.index,
        input_state: st.state
    });
    rebuildShellyApiSnapshot(context);
}

function merge(context, key, data) {
    const state = context.get('sw_' + key) || { output: null, apower: null, voltage: null, current: null, energy: null };
    if (data.output  !== undefined) state.output  = data.output;
    if (data.apower  !== undefined) state.apower  = data.apower;
    if (data.voltage !== undefined) state.voltage = data.voltage;
    if (data.current !== undefined) state.current = data.current;
    if (data.aenergy && data.aenergy.total !== undefined) state.energy = data.aenergy.total;
    context.set('sw_' + key, state);
}

const pl = msg.payload || {};
const topic = msg.topic || '';
const parts = topic.split('/');
const prefix = parts[0];
const last = parts[parts.length - 1];

// ===== VETEV A: odpoved na GetStatus -> topic 'nr_<key>/rpc', data v payload.result =====
if (prefix.indexOf('nr_') === 0 && last === 'rpc' && pl.result) {
    const key = prefix.slice(3);
    if (key.indexOf('-IN-') >= 0) {
        const ik = key.replace('-IN-', '#');
        if (inputLookup[ik] && pl.result.state !== undefined) {
            const st = context.get('in_' + ik) || { state: null };
            st.state = pl.result.state;
            context.set('in_' + ik, st);
            emitInput(node, context, ik, inputLookup[ik]);
        }
        return null;
    }
    if (lookup[key] && pl.result.output !== undefined) {
        merge(context, key, pl.result);
        emit(node, context, key, lookup[key]);
    }
    return null;
}

// ===== VETEV B: NotifyStatus z <prefix>/events/rpc =====
if (parts.length >= 2 && parts[parts.length - 2] === 'events' && last === 'rpc') {
    if (pl.method !== 'NotifyStatus' && pl.method !== 'NotifyFullStatus') return null;
    const params = pl.params || {};
    Object.keys(params).forEach(field => {

        // --- VYSTUPY: switch:N ---
        let m = field.match(/^switch:(\d+)$/);
        if (m) {
            const channel = parseInt(m[1], 10);
            const key = prefix + ':' + channel;
            const dev = lookup[key];
            if (!dev) {
                const knownPrefix = (ipByMqtt[prefix] !== undefined) ||
                                    (shellyDevices.switches || []).some(d => d.mqtt_id === prefix);
                if (knownPrefix) return;
                node.send({
                    topic: key, kind: 'output', order: 9999, unknown: true, device_name: key,
                    device_ip: ipByMqtt[prefix] ? ('http://' + ipByMqtt[prefix]) : null,
                    mqtt_id: prefix, channel: channel, output: null, has_data: false,
                    power_w: '--', voltage_v: '--', current_a: '--', energy_kwh: '--'
                });
                return;
            }
            merge(context, key, params[field]);
            emit(node, context, key, dev);
            return;
        }

        // --- VSTUPY: input:N ---
        m = field.match(/^input:(\d+)$/);
        if (m) {
            const idx = parseInt(m[1], 10);
            const ik = prefix + '#' + idx;
            const dev = inputLookup[ik];
            if (!dev) return; // nepojmenovany / nenakonfigurovany vstup -> nezobrazuj
            const data = params[field] || {};
            if (data.state !== undefined) {
                const st = context.get('in_' + ik) || { state: null };
                st.state = data.state;
                context.set('in_' + ik, st);
            }
            emitInput(node, context, ik, dev);
            return;
        }
    });
    return null;
}

return null;

