// ===== switch_control - "Switch - ovladani" =====

// Vstup A: toggle z karty -> Switch.Set
if (msg.payload === 'switchControl') {
    return {
        topic: msg.mqtt_id + '/rpc',
        payload: {
            id: 1,
            src: 'nodered',
            method: 'Switch.Set',
            params: { id: (msg.channel !== undefined ? msg.channel : 0), on: msg.on === true }
        },
        qos: 1, retain: false
    };
}

// Vstup C: ulozeni poradi karet (drag & drop z dashboardu)
// msg.order = [ "Linea_4PM_PRO:0", "BocniBrana:0", ... ]  (pole topicu v novem poradi)
if (msg.payload === 'saveOrder' && Array.isArray(msg.order)) {
    const shellyDevices = global.get('shellyDevices') || { switches: [] };
    const list = shellyDevices.switches || [];

    // poradove cislo podle topicu (mqtt_id + ':'/'#' + channel)
    const orderMap = {};
    msg.order.forEach((t, i) => { orderMap[t] = i; });

    const topicOf = (d) => {
        const ch = (d.channel !== undefined ? d.channel : 0);
        return d.mqtt_id + (d.kind === 'input' ? '#' : ':') + ch;
    };

    list.forEach(d => {
        const t = topicOf(d);
        if (orderMap[t] !== undefined) d.order = orderMap[t];
    });

    // seraď samotne pole switches podle order (aby to bylo konzistentni i jinde)
    list.sort((a, b) => {
        const oa = (a.order !== undefined ? a.order : 9999);
        const ob = (b.order !== undefined ? b.order : 9999);
        return oa - ob;
    });

    shellyDevices.switches = list;
    global.set('shellyDevices', shellyDevices);
    return null;
}

// Vstup B: vyzadej stav vsech zarizeni (Switch.GetStatus + Input.GetStatus)
if (msg.payload === 'reqStatus') {
    const shellyDevices = global.get('shellyDevices') || { switches: [] };
    const seen = {};

    (shellyDevices.switches || []).forEach(d => {
        if (!d.mqtt_id) return;
        if (!d.name || String(d.name).trim() === '') return;

        const ch = (d.channel !== undefined ? d.channel : 0);

        if (d.kind === 'input') {
            const ik = d.mqtt_id + '#' + ch;
            if (seen[ik]) return;
            seen[ik] = true;
            node.send({
                topic: d.mqtt_id + '/rpc',
                payload: {
                    id: 1,
                    src: 'nr_' + d.mqtt_id + '-IN-' + ch,
                    method: 'Input.GetStatus',
                    params: { id: ch }
                },
                qos: 1, retain: false
            });
        } else {
            const key = d.mqtt_id + ':' + ch;
            if (seen[key]) return;
            seen[key] = true;
            node.send({
                topic: d.mqtt_id + '/rpc',
                payload: {
                    id: 1,
                    src: 'nr_' + key,
                    method: 'Switch.GetStatus',
                    params: { id: ch }
                },
                qos: 1, retain: false
            });
        }
    });
    return null;
}

return null;

// ===== switch_set_page - "Set_Page_Switch" =====
const shellyDevices = global.get('shellyDevices') || global.get('defaultShellyDevices') || { switches: [] };

(shellyDevices.switches || []).forEach((dev, i) => {
    if (!dev.mqtt_id) return;
    if (!dev.name || String(dev.name).trim() === '') return;

    const channel = (dev.channel !== undefined ? dev.channel : 0);
    const ord = (dev.order !== undefined ? dev.order : i);

    if (dev.kind === 'input') {
        node.send({
            topic:       dev.mqtt_id + '#' + channel,
            kind:        'input',
            order:       ord,
            device_name: dev.name,
            device_ip:   dev.ip ? ('http://' + dev.ip) : null,
            mqtt_id:     dev.mqtt_id,
            index:       channel,
            input_state: null
        });
    } else {
        node.send({
            topic:       dev.mqtt_id + ':' + channel,
            kind:        'output',
            order:       ord,
            device_name: dev.name,
            device_ip:   'http://' + dev.ip,
            mqtt_id:     dev.mqtt_id,
            channel:     channel,
            output:      null,
            power_w:     '--',
            voltage_v:   '--',
            current_a:   '--',
            energy_kwh:  '--'
        });
    }
});

return null;
